{
  "ruleset_id": "cultural-grant-urban-stage",
  "rules": [
    {
      "description": "Project lead must be of legal age (18+)",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "team.project_lead_age", "op": "ge", "value": 18}
    },
    {
      "description": "Applicant co-financing must be at least 20% of budget",
      "severity": "major",
      "category": "budget",
      "condition": {"field": "budget.co_financing_pct", "op": "ge", "value": 20}
    },
    {
      "description": "Venue consent required for in-person events",
      "severity": "major",
      "category": "venue",
      "condition": {"field": "documents.venue_consent.present", "op": "eq", "value": true}
    },
    {
      "description": "Requested grant amount must not exceed 1,500,000 RUB",
      "severity": "critical",
      "category": "funding_limit",
      "condition": {"field": "application.requested_rub", "op": "le", "value": 1500000}
    }
  ]
}

{
  "ruleset_id": "supplementary-education-program",
  "rules": [
    {
      "description": "Organization must provide a valid educational activity license.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "documents.education_license.present", "op": "eq", "value": true}
    },
    {
      "description": "Program total hours must be at least 72.",
      "severity": "major",
      "category": "curriculum",
      "condition": {"field": "curriculum.total_hours", "op": "ge", "value": 72}
    },
    {
      "description": "At least 80% of teachers must have relevant qualifications.",
      "severity": "major",
      "category": "staffing",
      "condition": {"field": "staff.qualified_teachers_pct", "op": "ge", "value": 80}
    },
    {
      "description": "Delivery format must be either 'очно' or 'смешанно'.",
      "severity": "major",
      "category": "delivery",
      "condition": {"field": "programme.delivery_format", "op": "in", "value": ["очно", "смешанно"]}
    }
  ]
}

{
  "ruleset_id": "energy_efficiency_subsidy",
  "rules": [
    {
      "description": "Project must reduce energy consumption by at least 20%",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "project.energy_consumption_reduction_pct", "op": "ge", "value": 20}
    },
    {
      "description": "Applicant co-financing share must be at least 30%",
      "severity": "critical",
      "category": "financial",
      "condition": {"field": "budget.co_financing_pct", "op": "ge", "value": 30}
    },
    {
      "description": "Technical passport document must be attached to the application",
      "severity": "major",
      "category": "documentation",
      "condition": {"field": "documents.technical_passport.present", "op": "eq", "value": true}
    },
    {
      "description": "Project completion date must not be later than 31 December 2027",
      "severity": "critical",
      "category": "schedule",
      "condition": {"field": "project.completion_date", "op": "le", "value": "2027-12-31"}
    }
  ]
}

{
  "ruleset_id": "nordstar-main-track-v2.4",
  "rules": [
    {
      "description": "Applicant must be registered at least 24 months for the main track.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "org_v2.months_registered", "op": "ge", "value": 24}
    },
    {
      "description": "Requested amount cannot exceed EUR 250,000.",
      "severity": "major",
      "category": "budget",
      "condition": {"field": "org_v2.total_requested", "op": "le", "value": 250000}
    },
    {
      "description": "Independent audit report for the last completed fiscal year must be attached.",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.audit_report.present", "op": "eq", "value": true}
    },
    {
      "description": "Submission date must not be after 31 March 2027 inclusive.",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "org_v2.submission_date", "op": "before", "value": "2027-04-01"}
    },
    {
      "description": "Declared headcount in application must match annual report headcount.",
      "severity": "major",
      "category": "consistency",
      "condition": {"field": "org_v2.declared_headcount", "op": "consistent", "value": null}
    },
    {
      "description": "Annual report must be prepared under IFRS; non‑IFRS is a formal deficiency.",
      "severity": "minor",
      "category": "reporting",
      "condition": {"field": "annual_report.ifrs", "op": "eq", "value": true}
    }
  ]
}

{
  "ruleset_id": "primer-fund-grant-program-2026-v1",
  "rules": [
    {
      "description": "Organization must be registered at least 12 months before submission.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "application_form.months_registered", "op": "ge", "value": 12}
    },
    {
      "description": "Requested total cannot exceed EUR 100,000.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {"field": "application_form.requested_total_eur", "op": "le", "value": 100000}
    },
    {
      "description": "Equipment share in budget may not exceed 40%.",
      "severity": "major",
      "category": "budget_composition",
      "condition": {"field": "budget.row.equipment.share_pct", "op": "le", "value": 40}
    },
    {
      "description": "Application form document is required.",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.application_form.present", "op": "eq", "value": true}
    },
    {
      "description": "Detailed budget document is required.",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.budget.present", "op": "eq", "value": true}
    },
    {
      "description": "Registration certificate (registry extract) is required.",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.registration_cert.present", "op": "eq", "value": true}
    },
    {
      "description": "Latest financial statement is required.",
      "severity": "critical",
      "category": "documents",
      "condition": {"field": "documents.finance_statement.present", "op": "eq", "value": true}
    },
    {
      "description": "Submission date must be on or before 2026-10-01.",
      "severity": "major",
      "category": "deadline",
      "condition": {"field": "application_form.submission_date", "op": "before", "value": "2026-10-02"}
    },
    {
      "description": "Application form must be signed by the legal representative.",
      "severity": "critical",
      "category": "formal",
      "condition": {"field": "application_form.signature_present", "op": "eq", "value": true}
    },
    {
      "description": "Requested amount must match the detailed budget total exactly.",
      "severity": "major",
      "category": "consistency",
      "condition": {"field": "application_form.requested_total_eur", "op": "consistent", "value": null}
    },
    {
      "description": "Financial statement period must cover FY2025.",
      "severity": "minor",
      "category": "finance_period",
      "condition": {"field": "finance_statement.period", "op": "eq", "value": "FY2025"}
    }
  ]
}

{
  "ruleset_id": "capital_repair_program",
  "rules": [
    {
      "description": "Building must be constructed no later than 2005.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "building.construction_year", "op": "le", "value": 2005}
    },
    {
      "description": "Owners' approval must be at least 66%.",
      "severity": "major",
      "category": "approval",
      "condition": {"field": "owners.approval_pct", "op": "ge", "value": 66}
    },
    {
      "description": "Defect inspection report must be attached to the application.",
      "severity": "major",
      "category": "documentation",
      "condition": {"field": "documents.defect_report.present", "op": "eq", "value": true}
    },
    {
      "description": "Application submission date must be on or before April 1, 2027.",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "application.submission_date", "op": "before", "value": "2027-04-02"}
    }
  ]
}

{
  "ruleset_id": "medical-device-procurement",
  "rules": [
    {
      "description": "Medical device must have a valid registration certificate.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "documents.medical_registration.present", "op": "eq", "value": true}
    },
    {
      "description": "Remaining shelf life at delivery must be at least 12 months.",
      "severity": "major",
      "category": "quality",
      "condition": {"field": "product.expiry_months", "op": "ge", "value": 12}
    },
    {
      "description": "Cold-chain products require a documented cold chain protocol.",
      "severity": "major",
      "category": "logistics",
      "condition": {"field": "documents.cold_chain_protocol.present", "op": "eq", "value": true}
    },
    {
      "description": "Country of origin must be Russia or an EAEU member state.",
      "severity": "critical",
      "category": "origin",
      "condition": {"field": "product.origin_country", "op": "in", "value": ["Russia", "EAEU"]}
    }
  ]
}

{
  "ruleset_id": "preferential-microloan-msp",
  "rules": [
    {
      "description": "Годовая выручка компании не превышает 120 000 000 рублей.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "company.annual_revenue_rub", "op": "le", "value": 120000000}
    },
    {
      "description": "Просроченная задолженность отсутствует.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "company.overdue_debt", "op": "eq", "value": 0}
    },
    {
      "description": "Не менее 51% долей принадлежит российским владельцам.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "company.russian_ownership_pct", "op": "ge", "value": 51}
    },
    {
      "description": "Сумма займа не превышает 10 000 000 рублей.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "loan.requested_rub", "op": "le", "value": 10000000}
    }
  ]
}

{
  "ruleset_id": "municipal_subsidy_2026",
  "rules": [
    {
      "description": "Applicant must be registered for at least 12 months.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "applicant.registration_months", "op": "ge", "value": 12}
    },
    {
      "description": "Requested subsidy amount must not exceed 5,000,000 RUB.",
      "severity": "critical",
      "category": "budget",
      "condition": {"field": "application.requested_rub", "op": "le", "value": 5000000}
    },
    {
      "description": "Financial statement for the last year must be attached.",
      "severity": "major",
      "category": "documents",
      "condition": {"field": "documents.financial_statement.present", "op": "eq", "value": true}
    },
    {
      "description": "Application submission date must be on or before 2026-09-15 inclusive.",
      "severity": "critical",
      "category": "deadline",
      "condition": {"field": "application.submission_date", "op": "before", "value": "2026-09-16"}
    },
    {
      "description": "Applicant must have no tax arrears.",
      "severity": "critical",
      "category": "compliance",
      "condition": {"field": "applicant.tax_arrears", "op": "eq", "value": false}
    }
  ]
}

{
  "ruleset_id": "repair-works-tender",
  "rules": [
    {
      "description": "Supplier annual turnover must be at least 10,000,000 RUB.",
      "severity": "critical",
      "category": "financial_eligibility",
      "condition": {"field": "supplier.annual_turnover_rub", "op": "ge", "value": 10000000}
    },
    {
      "description": "Valid SRO certificate is required for admission.",
      "severity": "critical",
      "category": "documentation",
      "condition": {"field": "documents.sro_certificate.present", "op": "eq", "value": true}
    },
    {
      "description": "Sanctions check status must be 'clear'.",
      "severity": "critical",
      "category": "compliance",
      "condition": {"field": "supplier.sanctions_status", "op": "eq", "value": "clear"}
    },
    {
      "description": "Bid submission date must not be later than 20 November 2026.",
      "severity": "major",
      "category": "timeline",
      "condition": {"field": "bid.submission_date", "op": "le", "value": "2026-11-20"}
    }
  ]
}

{
  "ruleset_id": "applied-research-competition",
  "rules": [
    {
      "description": "Руководитель должен иметь степень кандидата или доктора наук",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "researcher.degree", "op": "in", "value": ["кандидат наук", "доктор наук"]}
    },
    {
      "description": "У руководителя должно быть не менее трёх публикаций в рецензируемых журналах",
      "severity": "major",
      "category": "eligibility",
      "condition": {"field": "researcher.peer_reviewed_publications", "op": "ge", "value": 3}
    },
    {
      "description": "Обязательно наличие согласия на размещение обезличенных данных исследования",
      "severity": "critical",
      "category": "compliance",
      "condition": {"field": "documents.open_data_consent.present", "op": "eq", "value": true}
    },
    {
      "description": "Заявленный бюджет должен совпадать с итогом сметы",
      "severity": "major",
      "category": "budget",
      "condition": {"field": "application.declared_budget_rub", "op": "consistent", "value": null}
    }
  ]
}

{
  "ruleset_id": "social_contract_eligibility",
  "rules": [
    {
      "description": "Household must be located in Moscow or Moscow region.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {"field": "household.region", "op": "in", "value": ["Moscow", "Moscow region"]}
    },
    {
      "description": "Monthly income per person must not exceed 25,000 RUB.",
      "severity": "critical",
      "category": "financial",
      "condition": {"field": "household.monthly_income_per_person_rub", "op": "le", "value": 25000}
    },
    {
      "description": "Personal data consent document must be present.",
      "severity": "major",
      "category": "compliance",
      "condition": {"field": "documents.personal_data_consent.present", "op": "eq", "value": true}
    },
    {
      "description": "Applicant employment status must be unemployed or job_seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {"field": "applicant.employment_status", "op": "in", "value": ["unemployed", "job_seeker"]}
    }
  ]
}
